console.log('after 1st click:', texts);
await page.screenshot({ path: '/tmp/pwcheck/after-click.png' });
await btn.click();
await page.waitForTimeout(300);
console.log('after 2nd click:', await page.locator('text=Кнопка нажата').allTextContents());
await page.waitForTimeout(4500);
console.log('after 5s (should be gone):', await page.locator('text=Кнопка нажата').allTextContents());
await page.screenshot({ path: '/tmp/pwcheck/after-hide.png' });
console.log('errors:', errors);
await browser.close();
EOF
