// @vitest-environment jsdom
import { describe, it, expect, beforeAll } from 'vitest';
import * as React from 'react';
import { createRoot } from 'react-dom/client';
import { act } from 'react';
import { ThemeProvider } from '@gravity-ui/uikit';
import { App } from './App';

(globalThis as any).IS_REACT_ACT_ENVIRONMENT = true;

beforeAll(() => {
  if (!window.matchMedia) {
    window.matchMedia = (q: string) => ({
      matches: false, media: q, onchange: null,
      addListener() {}, removeListener() {}, addEventListener() {}, removeEventListener() {}, dispatchEvent() { return false; },
    }) as any;
  }
});

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

describe('notify button', () => {
  it('shows toast on click and hides it after timeout', async () => {
    const container = document.createElement('div');
    document.body.appendChild(container);
    const root = createRoot(container);
    await act(async () => {
      root.render(<ThemeProvider theme="light"><App /></ThemeProvider>);
    });
    const btn = Array.from(document.querySelectorAll('button')).find((b) => b.textContent?.includes('Показать уведомление'))!;
    expect(btn).toBeTruthy();
    const count = () => document.body.textContent!.split('Кнопка нажата').length - 1;
    expect(count()).toBe(0);

    await act(async () => { btn.click(); });
    expect(count()).toBe(1);
    expect(document.body.textContent).toContain('Кнопка нажата 1 раз');
    expect(document.body.textContent).toContain('Уведомление');

    await act(async () => { btn.click(); });
    expect(count()).toBe(2);

    // still visible before autohide (4s)
    await act(async () => { await sleep(2000); });
    expect(count()).toBe(2);

    // autohide fired: toasts are leaving (exit CSS class applied on the transition wrapper)
    await act(async () => { await sleep(2500); });
    const toastEls = Array.from(document.querySelectorAll('[data-toast]')) as HTMLElement[];
    expect(toastEls.length).toBe(2);
    const exiting = toastEls.map((el) => (el.parentElement?.className ?? '') + ' ' + el.className);
    console.log('exit classes:', exiting);
    expect(exiting.every((c) => /exit/.test(c))).toBe(true);

    // jsdom never fires animationend; emulate the end of the exit animation so the list removes them.
    await act(async () => {
      toastEls.forEach((el) => el.dispatchEvent(new Event('animationend')));
      await sleep(50);
    });
    expect(count()).toBe(0);
    root.unmount();
  }, 15000);
});

